package com.ryanjei.orushio.pve.bootstrap;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class RuntimeConfigurationTest{@TempDir Path temp;@Test void 正常設定は通常モード(){RuntimeConfiguration c=RuntimeConfiguration.load(temp);assertTrue(c.configLoaded());assertFalse(c.diagnosticMode());assertEquals(8765,c.port());}@Test void system設定破損でも既定portの診断モード(){Path p=temp.resolve("config.yml");assertDoesNotThrow(()->Files.writeString(p,"broken"));RuntimeConfiguration c=RuntimeConfiguration.load(temp);assertTrue(c.diagnosticMode());assertEquals(8765,c.port());assertDoesNotThrow(()->assertEquals("broken",Files.readString(p)));}@Test void game設定破損でも診断モード(){assertDoesNotThrow(()->Files.writeString(temp.resolve("game-config.yml"),"broken"));assertTrue(RuntimeConfiguration.load(temp).diagnosticMode());}@Test void 未知schemaを変更しない()throws Exception{Path p=temp.resolve("config.yml");String value="schemaVersion: \"99\"\nhttpPort: \"9999\"\n";Files.writeString(p,value);assertTrue(RuntimeConfiguration.load(temp).diagnosticMode());assertEquals(value,Files.readString(p));}@Test void 不正portは既定portの診断モード()throws Exception{Files.writeString(temp.resolve("config.yml"),"schemaVersion: \"1\"\nhttpPort: \"invalid\"\n");RuntimeConfiguration c=RuntimeConfiguration.load(temp);assertTrue(c.diagnosticMode());assertEquals(8765,c.port());}}
